package com.shipflow.order;
import com.shipflow.common.exception.GlobalExceptionHandler;import com.shipflow.order.api.ShipmentOrderManagementController;import com.shipflow.order.api.model.*;import com.shipflow.order.application.*;import com.shipflow.security.SecurityConfig;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.context.TestConfiguration;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.*;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.oauth2.jwt.JwtDecoder;import org.springframework.test.web.servlet.MockMvc;import java.math.*;import java.time.*;import java.util.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(ShipmentOrderManagementController.class)@Import({SecurityConfig.class,GlobalExceptionHandler.class,ShipmentOrderManagementControllerWebMvcTest.C.class})class ShipmentOrderManagementControllerWebMvcTest{@Autowired MockMvc mvc;@MockBean ShipmentOrderQueryApplicationService query;@MockBean ShipmentOrderLifecycleApplicationService lifecycle;@TestConfiguration static class C{@Bean JwtDecoder jwtDecoder(){return t->{throw new org.springframework.security.oauth2.jwt.BadJwtException("test");};}}
 @Test void listsTenantOrdersWithFilters()throws Exception{when(query.list(7L,"DRAFT",3L,2,10)).thenReturn(new ShipmentOrderPageResponse(2,10,1,1,List.of(order())));mvc.perform(get("/api/v1/orders").param("status","DRAFT").param("storeId","3").param("page","2").param("pageSize","10").with(token())).andExpect(status().isOk()).andExpect(jsonPath("$.data.items[0].status").value("DRAFT")).andExpect(jsonPath("$.data.items[0].version").value(4));verify(query).list(7L,"DRAFT",3L,2,10);}
 @Test void getsOrderWithVersion()throws Exception{when(query.get(7L,9L)).thenReturn(order());mvc.perform(get("/api/v1/orders/9").with(token())).andExpect(status().isOk()).andExpect(jsonPath("$.data.version").value(4));}
 @Test void updatesDraftPayloadForJwtTenantAndUser()throws Exception{when(lifecycle.updateDraft(eq(7L),eq(2L),eq(9L),any(),eq("request-1"))).thenReturn(order());mvc.perform(put("/api/v1/orders/9").with(token()).with(csrf()).header("X-Request-Id","request-1").contentType("application/json").content("{\"version\":3,\"senderAddress\":{\"contactName\":\"A\",\"phone\":\"1\",\"countryCode\":\"CN\",\"city\":\"SZ\",\"addressLine1\":\"x\",\"postalCode\":\"1\"},\"receiverAddress\":{\"contactName\":\"B\",\"phone\":\"2\",\"countryCode\":\"US\",\"city\":\"LA\",\"addressLine1\":\"y\",\"postalCode\":\"2\"},\"items\":[{\"sku\":\"sku\",\"productName\":\"product\",\"quantity\":1,\"unitPrice\":2,\"currency\":\"USD\"}],\"remark\":\"draft\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.data.id").value(9)).andExpect(jsonPath("$.data.version").value(4));}
 @Test void platformCallerCannotListTenantOrders()throws Exception{mvc.perform(get("/api/v1/orders").with(jwt().jwt(j->j.subject("1")).authorities(new SimpleGrantedAuthority("scope:PLATFORM")))).andExpect(status().isForbidden());}
 private org.springframework.test.web.servlet.request.RequestPostProcessor token(){return jwt().jwt(j->j.subject("2").claim("tenant_id","7")).authorities(new SimpleGrantedAuthority("scope:TENANT"));}private ShipmentOrderResponse order(){return new ShipmentOrderResponse(9L,"SO9",8L,"DRAFT",new BigDecimal("12.50"),"USD",new BigDecimal("2.000"),4L,OffsetDateTime.parse("2026-08-13T00:00:00Z"));}}
